pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy a minimal token that implements transferFrom and records last transferred amount
        TokenMock token = new TokenMock();
        address from = address(0x123);
        address to = address(0x456);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint v = 1;
        uint _decimals = 2;
        // set allowance so that transferFrom wont revert
        vm.prank(from);
        token.approve(address(c), 2**256 - 1);
        // call the function
        c.transfer(from, address(token), tos, v, _decimals);
        // after call, the reference sets amount = 1 * 100 = 100, bug sets amount = 1 + 100 = 101
        // token's lastAmount is public, so we read it
        assertEq(token.lastAmount(), 100);
    }
}

