        address caddress = address(0x2);
        address[] memory tos = new address[](1);
        tos[0] = address(0x3);
        uint v = 1;
        uint decimals = 0;
        // We'll use a simple mock token that records balance
        MockToken token = new MockToken();
        caddress = address(token);
        // The reference transferFrom will be called, we need to make sure from has allowance
        token.approve(from, v * 10 ** decimals);
        // Pre-fund from with tokens
        token.mint(from, v * 10 ** decimals);
        vm.prank(from);
        bool success;
        try c.transfer(from, caddress, tos, v, decimals) returns (bool ok) {
            success = ok;
        } catch {
            success = false;
