pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock token that will revert if transferFrom is not called
        // We'll use a simple contract that tracks calls
        // But we must only interact through C's public surface
        // So we create a token that always reverts on transferFrom call
        // and ensure that in the reference version, the call reverts (so the transaction reverts)
        // but we catch the revert and assert false.
        // In the buggy version, the loop starts at 1, so for a single-element array,
        // no call is made, thus no revert, and we assert true.
        // Actually, we need to check something observable.
        // Simpler: Use a token that returns false from transferFrom (no revert).
        // The reference calls it once, and if it returns false, the loop reverts.
        // The buggy version calls nothing and returns true.

        // Deploy a token that returns false on transferFrom
        // Unfortunately we can't deploy another contract from the test without violating rules.
        // So we use a trick: use address(0) as token? That will revert on call with no code.
        // Reference will revert because call to address(0) with value transferFrom returns false (no code).
        // Buggy will skip and return true.
        // But we must catch the revert from the reference.

        address from = address(0x123);
        address token = address(0); // no code, call will return (success=false)
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 1;
        uint decimals = 0;

        // Reference: call to token address(0) will return success=false, so revert occurs.
        // We need to catch it.
        bool ok;
        try c.transfer(from, token, tos, v, decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference version, this call reverts (ok = false)
        // For the buggy version, loop skips, returns true (ok = true)
        // So we assert that the call should have reverted (i.e., ok == false)
        assertTrue(!ok);
    }
}

